from pathlib import Path
import hashlib
_md5 = hashlib.md5
def _compat_md5(data=b'', *args, **kwargs):
    kwargs.pop('usedforsecurity', None)
    return _md5(data, *args, **kwargs)
hashlib.md5 = _compat_md5
