CAP["fr"].update({"Transport helicopter command":"Commande de l'hélicoptère de transport","Place pickup point LZA":"Placer le point de récupération LZA","Place landing point LZB":"Placer la zone d'atterrissage LZB","Place hover point HOB":"Placer le point de vol stationnaire HOB","Battle Zone overview":"Vue d'ensemble de la zone de bataille","Battle Zone status and progress":"Etat et progression de la zone de bataille"})
CAP["de"].update({"Transport helicopter command":"Befehl für Transporthubschrauber","Place pickup point LZA":"Abholpunkt LZA platzieren","Place landing point LZB":"Landezone LZB platzieren","Place hover point HOB":"Schwebepunkt HOB platzieren","Battle Zone overview":"Uebersicht der Kampfzone","Battle Zone status and progress":"Status und Fortschritt der Kampfzone"})
CAP["es"] = {k: v.replace("mision", "misión").replace("paracaidas", "paracaídas").replace("aerea", "aérea").replace("insercion", "inserción").replace("tactica", "táctica").replace("seleccionada", "seleccionada") for k, v in CAP["es"].items()}

def make_styles():
 s=getSampleStyleSheet(); s.add(ParagraphStyle(name="CoverX",parent=s["Title"],alignment=TA_CENTER,fontSize=27,leading=32,textColor=colors.HexColor("#123846"))); s.add(ParagraphStyle(name="SubX",parent=s["Normal"],alignment=TA_CENTER,fontSize=10,leading=14,textColor=colors.HexColor("#536371"))); s.add(ParagraphStyle(name="H1X",parent=s["Heading1"],fontSize=18,leading=22,textColor=colors.HexColor("#123846"),spaceBefore=8,spaceAfter=6)); s.add(ParagraphStyle(name="H2X",parent=s["Heading2"],fontSize=14,leading=18,textColor=colors.HexColor("#197a75"),spaceBefore=8,spaceAfter=4)); s.add(ParagraphStyle(name="BodyX",parent=s["BodyText"],fontSize=9.5,leading=13.5,spaceAfter=5)); s.add(ParagraphStyle(name="CapX",parent=s["Normal"],alignment=TA_CENTER,fontSize=8,leading=10,textColor=colors.HexColor("#536371"))); return s

def pics(key,lang,s):
 cells=[]
 for fn,caption in IMAGES[key]:
  im=Image(str(IMG/fn),width=78*mm,height=52*mm); im._restrictSize(78*mm,52*mm); cells.append([im,Paragraph(CAP[lang][caption],s["CapX"])])
 rows=[cells[i:i+2] for i in range(0,len(cells),2)]
 if rows and len(rows[-1])==1: rows[-1].append("")
 t=Table(rows,colWidths=[82*mm,82*mm],hAlign="LEFT"); t.setStyle(TableStyle([("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),0),("RIGHTPADDING",(0,0),(-1,-1),4),("TOPPADDING",(0,0),(-1,-1),3),("BOTTOMPADDING",(0,0),(-1,-1),8)])); return t

def footer(c,doc):
 c.saveState(); c.setFont("Helvetica",8); c.setFillColor(colors.HexColor("#66757d")); c.drawString(18*mm,10*mm,"STW Divide And Conquer"); c.drawRightString(A4[0]-18*mm,10*mm,f"Page {doc.page}"); c.restoreState()

def build(lang):
 t=DATA[lang]; s=make_styles(); story=[Spacer(1,35*mm),Paragraph(t["title"],s["CoverX"]),Paragraph(t["author"],s["SubX"]),Spacer(1,8*mm),Paragraph(t["subtitle"],s["SubX"]),Spacer(1,8*mm),Image(str(IMG/"CaptainSprocketPatch.png"),width=120*mm,height=40*mm),PageBreak()]
 story += [KeepTogether([Paragraph(t["general"],s["H1X"]),Paragraph(t["warning"],s["BodyX"])]), KeepTogether([Paragraph(t["map"],s["H1X"]),Paragraph(t["mapbody"],s["BodyX"]),pics("map",lang,s)]), KeepTogether([Paragraph(t["campaign"],s["H1X"]),Paragraph(t["campaignbody"],s["BodyX"])]),PageBreak(),Paragraph(t["missions"],s["H1X"])]
 for k, body in (("stronghold","strongbody"),("cqb","cqbody"),("sf","sfbody"),("bz","bzbody")): story += [KeepTogether([Paragraph(t[k],s["H2X"]),Paragraph(t[body],s["BodyX"]),pics(k,lang,s)])]
 story += [PageBreak(),KeepTogether([Paragraph(t["surveillance"],s["H1X"]),Paragraph(t["air"],s["BodyX"]),pics("air",lang,s)]),KeepTogether([Paragraph(t["ally"],s["BodyX"]),pics("ally",lang,s)]),PageBreak(),Paragraph(t["wheel"],s["H1X"])]
 for k in ("deployment","recon","transport","support"):
  extra = [Paragraph(t["transportdetail"],s["BodyX"])] if k == "transport" else []
  story += [KeepTogether([Paragraph(t[k],s["H2X"]),Paragraph(t[k+"body"],s["BodyX"])] + extra + [pics(k,lang,s)])]
 filename = f"STWDivideAndConquerManual-{lang}.pdf"
 SimpleDocTemplate(str(OUT/filename),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=16*mm,bottomMargin=16*mm,title=t["title"],author=t["author"]).build(story,onFirstPage=footer,onLaterPages=footer)

if __name__ == "__main__":
 for lang in ("en","es","fr","de"): build(lang); print(f"built {lang}")
